@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Override
    public String getUrl() {
        return "http://localhost:" + port;
    }

    @Test
    void filterNarrowsAndRestoresTheGrid() {
        GridElement grid = GridElement.get(page);
        TextFieldElement filter = new TextFieldElement(page.locator("vaadin-text-field"));

        grid.waitForGridToStopLoading();
        assertEquals("Filter by name", filter.getPlaceholder());
        assertEquals("", filter.getValue());
        awaitRowCount(grid, 500);

        for (String typed : List.of("vir", "VIR", "Vir")) {
            filter.setValue(typed);
            awaitRowCount(grid, 15);
            grid.assertCellContent(0, 1, "Virtanen");
        }

        filter.setValue("qvist");
        awaitRowCount(grid, 14);
        grid.assertCellContent(0, 1, "Lindqvist");

        filter.setValue("");
        awaitRowCount(grid, 500);
    }

    private void awaitRowCount(GridElement grid, int expected) {
        grid.waitForGridToStopLoading();
        assertEquals(expected, await(grid::getTotalRowCount, expected),
                "grid row count for filter '"
                        + new TextFieldElement(page.locator("vaadin-text-field")).getValue() + "'");
    }

    /** Polls a value for a few seconds, so client-server round trips can settle. */
    private int await(IntSupplier actual, int expected) {
        int value = actual.getAsInt();
        for (int attempt = 0; attempt < 50 && value != expected; attempt++) {
            page.waitForTimeout(100);
            value = actual.getAsInt();
        }
        assertTrue(value >= 0);
        return value;
    }
}
